/* Advanced1 — constructive review, evidence and workload trade-offs. */
(function(){
 const N=AG.aws.n,clone=x=>JSON.parse(JSON.stringify(x)),R='us-east-1',A='123456789012',NAME='shop-review',BUCKET='wa-audit';
 const TRAIL=`arn:aws:cloudtrail:${R}:${A}:trail/${NAME}`,ALB=`arn:aws:elasticloadbalancing:${R}:${A}:loadbalancer/app/shop-review/0000000000000021`,TOPIC=`arn:aws:sns:${R}:${A}:review-alerts`;
 const canonical=(v,key='')=>{if(['Action','Resource','aws:SourceArn','s3:x-amz-acl','Service'].includes(key)&&(typeof v==='string'||Array.isArray(v)&&v.every(x=>typeof x==='string')))return (Array.isArray(v)?v:[v]).slice().sort();if(Array.isArray(v)){const a=v.map(x=>canonical(x));if(a.every(x=>x&&typeof x.Sid==='string'))a.sort((a,b)=>a.Sid.localeCompare(b.Sid));return a;}return v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k],k)])):v;};
 const same=(a,b)=>JSON.stringify(canonical(a))===JSON.stringify(canonical(b));
 const POLICY={Version:'2012-10-17',Statement:[{Sid:'ACL',Effect:'Allow',Principal:{Service:'cloudtrail.amazonaws.com'},Action:'s3:GetBucketAcl',Resource:'arn:aws:s3:::'+BUCKET,Condition:{StringEquals:{'aws:SourceArn':TRAIL}}},{Sid:'Write',Effect:'Allow',Principal:{Service:'cloudtrail.amazonaws.com'},Action:'s3:PutObject',Resource:`arn:aws:s3:::${BUCKET}/AWSLogs/${A}/*`,Condition:{StringEquals:{'s3:x-amz-acl':'bucket-owner-full-control','aws:SourceArn':TRAIL}}}]};
 const SELECTORS=[{ReadWriteType:'All',IncludeManagementEvents:true,DataResources:[]}];
 const ALARM={AlarmName:'review-5xx',Namespace:'AWS/ApplicationELB',MetricName:'HTTPCode_Target_5XX_Count',Dimensions:[{Name:'LoadBalancer',Value:'app/shop-review/0000000000000021'}],Statistic:'Sum',Unit:'Count',Threshold:5,ComparisonOperator:'GreaterThanThreshold',Period:60,EvaluationPeriods:2,DatapointsToAlarm:2,TreatMissingData:'missing',ActionsEnabled:true,AlarmActions:[TOPIC]};
 const Q=(q,correct,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};};
 const files={'trail-policy.json':{desc:'Exact CloudTrail service/account path with trail SourceArn; preserve bucket evidence',content:JSON.stringify(POLICY,null,2)},'management.json':{desc:'Read and write management events; no separately billed data-event selector in this fixture',content:JSON.stringify(SELECTORS,null,2)},'5xx-alarm.json':{desc:'Reviewed component diagnostic alarm; Count/Sum, 2 of 2×60s; not a customer error-rate SLO',content:JSON.stringify(ALARM,null,2)},'review.txt':{desc:'Fictional review scope, owners and remaining runtime work',content:'ShopKaro:40 engineers/3 teams, checkout workload. Three declared configuration risks:DB HA/backups; reviewed 5xxalarm; scoped multiRegion management trail logging/validation. Fix configuration then retain runtime work:restore and business-ID reconciliation, actual SLO and alarm delivery, S3 logs/digests plus validation. Zero declared config findings is not an AWS WA assessment/certificate.'}};
 function seed(interview=false){return {region:R,now:'2026-10-27T12:00:00Z',callerIdentity:{Account:A,UserId:'TRAINING',Arn:`arn:aws:iam::${A}:role/review-operator`},rds:[{id:'orders',resourceId:'db-original-review-orders',name:'orders',engine:'postgres',class:'db.t3.medium',state:'available',multiAZ:interview,backupRetention:interview?7:0,encrypted:true,publicAccess:false,deletionProtection:true,storage:100,dataFixture:[{orderId:'accepted101',total:499}]}],buckets:[{name:BUCKET,bucketId:'original-review-evidence',region:R,public:false,bpa:{BlockPublicAcls:true,IgnorePublicAcls:true,BlockPublicPolicy:true,RestrictPublicBuckets:true},objects:[{key:'original.txt',body:'TEST original review evidence',size:29}],...(interview?{policy:clone(POLICY)}:{})}],elbs:[{id:ALB,arn:ALB,name:'shop-review',fixtureId:'original-review-alb',type:'application',scheme:'internet-facing'}],topics:[{name:'review-alerts',arn:TOPIC,topicId:'original-review-topic',attributes:{FifoTopic:'false'},subscriptions:[]}],alarms:interview?[{name:'review-5xx',alarmId:'original-review-alarm',revision:1,definition:clone(ALARM),state:'ALARM'}]:[],trails:interview?[{name:NAME,arn:TRAIL,homeRegion:R,trailId:'original-review-trail',revision:1,bucket:BUCKET,multi:false,global:false,validation:false,logging:false,selectors:[{ReadWriteType:'WriteOnly',IncludeManagementEvents:false,DataResources:[]}]}]:[],managementEvents:[{EventId:'training-change101',EventName:'ModifyDBInstance',EventSource:'rds.amazonaws.com',EventTime:'2026-10-26T11:00:00Z',Username:'course-operator',ReadOnly:'false',Resources:[{ResourceType:'AWS::RDS::DBInstance',ResourceName:'orders'}],CloudTrailEvent:'{"training":true,"reason":"console change without review"}'}],capacityMetrics:[{seriesId:'original-review-errors',version:1,period:60,namespace:'AWS/ApplicationELB',metric:'HTTPCode_Target_5XX_Count',unit:'Count',dimensions:clone(ALARM.Dimensions),points:[{Timestamp:'2026-10-27T11:58:30Z',SampleCount:1200,Sum:8},{Timestamp:'2026-10-27T11:59:30Z',SampleCount:1200,Sum:9}]}]};}
 const initial=seed(),db=s=>s.account.rds.find(r=>r.id==='orders');
 function preserved(s){const a=s.account,b=a.buckets.find(b=>b.name===BUCKET),d=db(s);return a.rds.length===1&&d?.resourceId==='db-original-review-orders'&&d.engine==='postgres'&&d.class==='db.t3.medium'&&d.storage===100&&d.encrypted&&!d.publicAccess&&d.deletionProtection&&same(d.dataFixture,initial.rds[0].dataFixture)&&a.buckets.length===1&&b?.bucketId==='original-review-evidence'&&!b.public&&same(b.bpa,initial.buckets[0].bpa)&&b.objects.length===1&&b.objects[0].key==='original.txt'&&b.objects[0].body==='TEST original review evidence'&&same(a.elbs,initial.elbs)&&a.topics.length===1&&a.topics[0].topicId==='original-review-topic'&&a.topics[0].arn===TOPIC&&same(a.managementEvents,initial.managementEvents);}
 const database=s=>db(s)?.state==='available'&&db(s).multiAZ&&db(s).backupRetention>=7;
 function alarm(s){const a=s.account.alarms.find(a=>a.name==='review-5xx'),snap=a&&AG.capacityAlarmSnapshot(s.account,a);return s.account.alarms.length===1&&!!a&&same(a.definition,ALARM)&&snap.state==='ALARM'&&snap.source==='fixture-metrics'&&snap.seriesId==='original-review-errors'&&snap.version===1&&snap.points.length===2&&(s.account.capacityAlarmReads||[]).some(r=>r.alarmId===a.alarmId&&r.revision===a.revision&&r.source===snap.source&&r.state===snap.state&&r.seriesId===snap.seriesId&&r.version===snap.version&&same(r.view,a.definition));}
 function trail(s,interview=false){const t=s.account.trails.find(t=>t.name===NAME),b=s.account.buckets.find(b=>b.name===BUCKET);return s.account.trails.length===1&&!!t&&(!interview||t.trailId==='original-review-trail')&&t.arn===TRAIL&&t.homeRegion===R&&t.bucket===BUCKET&&!t.prefix&&t.multi&&t.global&&t.validation&&t.logging&&same(t.selectors,SELECTORS)&&same(b?.policy,POLICY)&&AG.auditTrailAccess(s.account,t)&&(s.account.trailReads||[]).some(r=>r.trailId===t.trailId&&r.revision===t.revision&&r.destinationAllowed&&same(r.view,t));}
 const solution=['aws s3api put-bucket-policy --bucket wa-audit --policy file://trail-policy.json','aws rds modify-db-instance --db-instance-identifier orders --multi-az --backup-retention-period 7 --apply-immediately','aws rds wait db-instance-available --db-instance-identifier orders','aws cloudwatch put-metric-alarm --cli-input-json file://5xx-alarm.json','aws cloudwatch describe-alarms --alarm-names review-5xx','aws cloudtrail create-trail --name shop-review --s3-bucket-name wa-audit --is-multi-region-trail --include-global-service-events --enable-log-file-validation','aws cloudtrail start-logging --name shop-review','aws cloudtrail get-trail-status --name shop-review'];
 const tasks=[{text:'Original orders, private evidence bucket, ALB/topic and seeded events preserved',check:preserved},{text:'Original DB available with Multi-AZ and≥7 days backups; no restore claim',check:database},{text:'Reviewed Count/Sum 5xx alarm with fresh supplied-period ALARM read; actual SLO not claimed',check:alarm},{text:'Scoped multi-Region/global management trail logging+validation configuration and current status read',check:s=>trail(s)}];
 const isolution=['aws cloudtrail update-trail --name shop-review --is-multi-region-trail --include-global-service-events --enable-log-file-validation','aws cloudtrail put-event-selectors --trail-name shop-review --event-selectors file://management.json','aws cloudtrail start-logging --name shop-review','aws cloudtrail get-trail-status --name shop-review'];
 const itasks=[{text:'Original evidence/orders/ALB/topic/events preserved; DB HA/backups remain configured',check:s=>preserved(s)&&database(s)&&s.account.alarms.length===1&&same(s.account.alarms[0].definition,ALARM)},{text:'Original trail repaired:All management, flags, logging and current status; no backfill/delivery claim',check:s=>trail(s,true)}];
 function plan(k){const p=[{rps:350,cpu:1,rate:.18},{rps:500,cpu:2,rate:.25},{rps:650,cpu:4,rate:.40}][k.size],days=[1,7,14][k.backups],retention=[7,30,90][k.logs],spot=[0,.25,.5][k.spot],onDemand=12-Math.floor(12*spot),survivors=onDemand-Math.ceil(onDemand/3),capacity=survivors*p.rps*.7,db=400+1200*(k.cache?.2:1)+(k.edge?0:200),cost=12*100*p.rate*(1-.75*spot)+(k.ha?240:120)+days*2+k.cache*35+k.edge*15+retention*.4,cpu=12*100*p.cpu,risks=[!k.ha||days<7,capacity<2000,db>800,retention<30].filter(Boolean).length;return {days,retention,capacity,db,cost,cpu,risks,ok:risks===0&&cost<=650&&cpu<=3000};}
 AG.registerLevels('advanced',[{
  id:'wellarch',icon:'🏛️',title:'Well-Architected — evidence aur trade-offs',badge:'Pillar Pandit',
  objectives:['Six pillars ko business risks/evidence se map karna','Scope/lens, HRI/MRI improvement plan aur milestones explain karna','Cost, failure budget aur resource efficiency ke trade-offs calculate karna','Original data preserve karke three declared configuration risks repair karna'],
  hook:{when:'ShopKaro course story — fictional',title:'Series A review:40 engineers, 3 teams, budget limited',text:'Mahasale ke baad Neha ke paas shiny architecture diagram hai, par four incidents ka evidence scattered hai. Database restore kab test hua? Console change kisne kiya? Alert owner kaun? Ravi har service add karna chahta hai; reviewer business impact aur verified improvement poochta hai.',mission:'Six pillars se constructive review karo, critical risks prioritize karo aur smallest defensible improvement plan likho. Course scanner 3 configuration contracts check karta hai; full AWS WA assessment, certificate ya launch approval nahi.'},
  steps:[
   {q:'Framework review ka output service checklist kyun nahi?',analogy:'Restaurant inspection conversation menu, food safety, staffing aur delivery promises samajhti hai. New oven khareedna missing hygiene record ka answer nahi.',body:'<p>A workload is a set of components delivering business value. Define checkout boundary, customers, accounts/Regions, dependencies, owner and business objectives before choosing a lens. AWS describes the review as a constructive conversation, not an audit mechanism or certification.</p>',points:['Six questions:Operational Excellence→operate/improve? Security→protect/access/detect? Reliability→recover and meet demand? Performance Efficiency→right resources? Cost Optimization→business value per spend? Sustainability→resource waste/environmental impact?','Tiny scope:ShopKaro checkout accepts orders; third-party payment/email dependencies have owners and failure contracts. Marketing site metrics cannot stand in for checkout outcomes.','Hands-on:dry run mein each component par evidence question answer karo. Expected output is a risk plus an owner/test, not a universal production stack.'],asli:'Review early, at meaningful changes/milestones and after incidents. Pick an ongoing cadence; quarterly is an example, not a mandatory AWS schedule.'},
   {q:'Six pillars ke principles action mein kaise dikhte hain?',analogy:'Restaurant SOP, locks, backup stove, right oven, portion budget aur food waste related hain; har concern ka primary question alag hai.',body:'<p>Operations:small reversible changes, observability and learning. Security:identity foundation, least privilege, layers and traceability. Reliability:bounded capacity, automatic recovery where appropriate and tested recovery. Performance:measure resource choices, experiment and use suitable managed services. Cost:measure business output/cost and eliminate waste. Sustainability:understand impact, maximize useful resource utilization and reduce unnecessary work.</p>',points:['Overlap normal hai:versioned IaC improves operations and recovery; encryption affects security, cost and performance. Choose primary pillar from the observed problem, then record secondary effects.','Galti jo sab karte hain:every Auto Scaling/CDN item Reliability mein daalna. If goal is selecting resources for measured response time, primary concern Performance Efficiency hai.','Hands-on:six-bin game includes all six pillars. Expected explanations name the stated objective and acknowledge overlap.'],asli:'A pillar label is a starting question; a service name alone cannot identify the root cause or close a risk.'},
   {q:'Risk ko budget ke against prioritize kaise karein?',analogy:'Leaking gas line aur expensive tablecloth dono issues hain; business impact, urgency aur mitigation effort equal nahi.',body:'<p>AWS WA Tool captures answers and high/medium risk issues with an improvement plan. Assess impact, likelihood/exposure, dependencies, effort, owner and verification. A course scanner can check selected fields; scanner findings are explicitly declared contracts, not official HRI/MRI ratings.</p>',points:['Hypothetical quote:single-AZ DB$120/month versus Multi-AZ$240/month, excluding other meters. Spend difference$120/month may address the stated AZ-HA risk, but does not buy tested regional recovery or a fixed availability percentage.','Cost versus risk:cache lowers eligible read load but adds staleness/operating work. Spot discounts apply to interruptible capacity; protect critical serving with an adequate On-Demand base and reviewed recovery. Managed services still need boundaries, quotas and ownership.','Galti jo sab karte hain:cheapest option without constraints, or cheapest-looking graph after deleting business work. Compare compliant alternatives first, then cost per useful output.'],asli:'Risk acceptance needs an explicit authorized owner, expiry and compensating controls. Changing an answer to hide a risk is not mitigation.'},
   {q:'WA Tool, lenses aur milestones ka workflow kya hai?',analogy:'Health record patient, specialist lens, evidence and follow-up visit rakhta hai. Same questionnaire every patient ke liye complete diagnosis nahi.',body:'<p>Define workload/review owner/environment/Regions. Framework lens is automatically applied; choose applicable Lens Catalog or custom lenses. Each lens has its own questions, best practices, notes and improvement plan. Current examples include Serverless Applications Lens and SaaS Lens; verify applicability/version, not a fixed 50-question promise.</p>',points:['Read source/evidence before answering. Save an initial milestone, prioritize improvement items, implement/test, then save a new milestone. Milestones record state at a point in time; a changed answer does not execute a deployment.','Tool use has no additional charge; resources/tests used for improvements can be billable. The local lab does not invoke AWS WA Tool or create an official risk report.','Hands-on:optional approved real-AWS exercise:Workloads→Define workload→scope/owner→choose applicable lenses→review evidence/notes→Save milestone. Expected artifact is a documented baseline and improvement plan.'],asli:'Use the actual selected lens questions; count and content evolve. Review the workload and its business dependencies, rather than reciting a memorized question count.'},
   {q:'Backup retention aur restored business state mein kitna gap hai?',analogy:'Restaurant ke fridge mein spare ingredients hona cooked meal deliver hone ka proof nahi. Recovery recipe aur actual rehearsal chahiye.',body:'<p>Multi-AZ HA, backups/PITR, replicas and regional DR address different failures. RPO is tolerated data loss window; RTO is tolerated recovery time. Recovery includes permissions/keys, networking, application configuration, dependencies and business reconciliation. A snapshot or Available status alone does not demonstrate those outcomes.</p>',points:['Example contract:restore into a new isolated target, verify accepted order IDs/totals and application behavior, record actual data point/time and recovery duration. Keep production source and evidence intact.','Galti jo sab karte hain:backup retention 7 days ko RPO 7 days ya RTO 7 minutes bolna. Retention is how long recovery history is kept; capture cadence/latest restorable point and measured recovery determine actual recovery evidence.','Production me kya hota hai:key permission, missing secret, stale endpoint or untested restore process blocks recovery even when backup status is available. Rehearse failure modes/quotas in approved isolation.','Hands-on:terminal repairs HA/backups and waits for configuration availability. Expected:original orders preserved. No SQL restore/failover or RTO/RPO measurement is claimed locally.'],asli:'Recovery test and reconciliation remain named improvement items after configuration changes; do not close the whole reliability review from two flags.'},
   {q:'Who changed the DB? CloudTrail aur alarms alag proof kyun?',analogy:'Cash register audit tells who changed a price. Queue wait meter shows current delay. Turning on a recorder does not recreate last month’s missing recording.',body:'<p>CloudWatch metrics/logs/traces answer operational questions; CloudTrail records supported account/API activity. Event history offers the last 90 days of management events in the selected Region, independently of a newly created trail. Trails configure ongoing selected delivery; S3/object data events need separate reviewed selectors/costs. A multi-Region trail covers enabled Regions, not every possible operation.</p>',points:['CloudTrail destination needs usable S3 policy:GetBucketAcl and PutObject to the account AWSLogs path, reviewed SourceArn and bucket-owner-full-control condition. Multi-Region/global flags, management selector, logging status and destination evidence are separate checks.','Enabling log-file validation allows future signed digest delivery; actual integrity validation is another action. IsLogging=true and even a synthetic Moto LatestDeliveryTime cannot prove delivered files or validated digests.','Hands-on:lookup-events shows seeded TRAINING change evidence in-app. Lab21 actual LookupEvents is unsupported 500; Moto also accepts missing bucket policy and fabricates delivery status. Both gaps are explicit.','Production me kya hota hai:wrong bucket/KMS/selector scope creates gaps while control-plane config exists. Verify delivered logs/digests, current errors/permissions and actual alarm actions; preserve old evidence.'],asli:'An alarm detects a component symptom; Event history can explain a management change. Neither establishes every business outcome or a full security review.'},
   {q:'Cost Optimization aur Sustainability same score hain?',analogy:'Discounted electricity bill aur fewer wasted meals different outcomes hain. A cheaper rate can leave the same kitchen running all night.',body:'<p>Track cost per successful order alongside resource use per useful output. Right-size, remove idle work/data and improve code, storage and access patterns. A commitment/Spot discount lowers price without necessarily reducing resource-hours. Architecture/CPU migration such as Graviton needs compatibility and representative benchmarks.</p>',points:['Course board assumes 12 workers×100 active hours/month. Profile M uses 2 vCPU→2400app vCPU-hours/month. A 25% Spot share can lower modeled price while the same 2400 resource-hours remain. This is not an energy/carbon estimate.','Region choice must satisfy latency, data residency, service availability and recovery needs alongside environmental goals; no single universal greenest Region claim. Do not sacrifice required redundancy to make resource count smaller.','Galti jo sab karte hain:select the biggest instance for safety without measurements, or call a discount a measured carbon reduction. Check throughput/tails, utilization and total useful work.','Hands-on:planner shows explicit fictional component quotes, post-AZ/Spot-independent critical capacity, modeled DB pressure and app resource-hours. Actual uptime/p95/security score are not inferred.'],asli:'The board narrows a decision with declared assumptions. Production sizing, environmental impact and customer SLO need real evidence and broader meters.'},
   {q:'ADR aur improvement ticket mein exactly kya likhein?',analogy:'Restaurant menu change note records why a dish changed, who tests, expected effect and how to revert. A receipt for new equipment is not a success report.',body:'<p>Use a small ADR:context/requirement→options→chosen trade-off→consequences/residual risk→owner→verification/rollback trigger. An improvement item also needs priority, due date and acceptance evidence. Re-review when assumptions, dependencies or significant incidents change.</p>',points:['Tiny ADR:AZ-loss objective outweighs hypothetical$120/month DB quote delta. Enable Multi-AZ/backups, preserve source, test restore in an approved sandbox; accept no regional-DR claim. Owner:Ravi; success:documented config plus separately measured/reconciled recovery.','Galti jo sab karte hain:0scanner findings=all six pillars passed. The local scanner checks 3declared configuration contracts; identity, deployment, performance, sustainability and runtime outcomes still need review.','Hands-on:finish terminal, then write one acceptance statement that names verified config and one unverified runtime item. Expected:no fake certificate, invented company incident or automatic business launch approval.'],asli:'A constructive review improves decisions and evidence over time. The report must make the remaining uncertainty visible to the next owner.'}
  ],
  myth:[{myth:'A completed WA questionnaire certifies production availability.',sach:'Review captures answers, evidence and improvements; it is not a runtime test, compliance certificate or guaranteed SLO.'},{myth:'Lowest cost option is the correct architecture.',sach:'First satisfy business, security/recovery and performance constraints; compare cost among defensible alternatives.'},{myth:'Backup 7 days means RTO 7 minutes and RPO 7 days.',sach:'Retention, capture/recovery point and measured recovery time are different quantities; rehearse and reconcile.'},{myth:'Discounts prove lower environmental impact.',sach:'Price changes need not reduce resource use. Measure useful work/resource impact; preserve required resilience.'}],
  playbook:{title:'Review se verified improvement tak',use:['Before meaningful design/launch changes, after incidents and on a workload-appropriate cadence.','When teams disagree:define the business constraint and evidence before selecting a service.','For a bounded improvement backlog with owners, verification and residual risk.'],avoid:['A fixed question count or a one-time certificate mindset.','Hiding risks by changing answers or deleting evidence/business work.','Invented uptime/security/carbon scores from a few configuration knobs.'],how:['Scope workload, dependencies and business SLO/RTO/RPO.','Choose applicable lens; gather config, runtime and business evidence.','Prioritize risks by impact/effort/dependencies with owners and expiry.','Implement a small tested change, verify the promised boundary, record milestone/ADR and revisit.'],redflags:['Backup exists but no restore/reconciliation evidence.','Alarm/trail name exists but unit/dimension/permission/selector/delivery is missing.','Spend falls but resource-hours, failures or lost work rise.'],rule:'Which customer outcome can fail, what evidence supports the risk, and what is the smallest tested improvement with an owner?'},
  exam:[{cue:'Review the whole workload',pick:'Six pillars + requirements; constructive conversation'},{cue:'Selected lens questions',pick:'Scope/version-specific; no fixed 50 question rule'},{cue:'HRI/MRI',pick:'Prioritized improvement plan + owner/evidence'},{cue:'Milestone',pick:'Point-in-time review state; not a deployment'},{cue:'Backup retention versus recovery',pick:'RTO/RPO need measured restore and reconciliation'},{cue:'Who changed a resource?',pick:'CloudTrail management history; Region/90 day scope'},{cue:'Logging and validation flags',pick:'Config first; delivered logs/digests and validation separately'},{cue:'Cheapest suitable design',pick:'Meet constraints before optimizing cost'},{cue:'Sustainability versus discount',pick:'Resource/useful-output evidence, not price alone'}],
  lesson:['<h3>Kab kya — compare evidence</h3><div class="tbl-wrap"><table class="review-table"><tr><th>Need</th><th>Use</th><th>Boundary</th></tr><tr><td>Workload trade-offs</td><td>WA Framework/Tool + applicable lens</td><td>Answers/notes do not run tests</td></tr><tr><td>Point-in-time review</td><td>Milestone + improvement plan</td><td>New milestone is not deployment</td></tr><tr><td>Current component symptom</td><td>Metrics/logs/traces + alarms</td><td>Correct unit/dimension/freshness</td></tr><tr><td>Management change</td><td>CloudTrail Event history/trail</td><td>Region/window/selectors/delivery</td></tr><tr><td>Recovery promise</td><td>Restore/failure drill + business reconciliation</td><td>Config availability is insufficient</td></tr><tr><td>Efficiency objective</td><td>Useful output per resource and cost</td><td>Discount alone is not resource reduction</td></tr></table></div><p>Phone par table sideways swipe karo.</p><p><b>Decision tree:</b> Customer constraint unclear? Define scope/SLO/recovery first. Constraint clear? Find missing evidence→classify primary pillar and overlaps→prioritize impact/effort→choose smallest reversible improvement. Config changed? Verify config, then actual runtime/business outcome. Assumption changed? Re-review and record milestone/ADR.</p>'],
  stages:[
   {type:'dryrun',title:'🧪 Review the workload, not just the boxes',intro:'Fictional ShopKaro review. Next click karo; choose the evidence that answers the stated business question.',lesson:'A pillar identifies a question; the improvement needs scope, owner, configuration evidence and an appropriate runtime/business test.',nodes:[N('app',150,150,{label:'Checkout scope'}),N('alb',470,150,{label:'Tail / errors'}),N('rds',790,150,{label:'Orders recovery'}),N('s3',790,420,{label:'Audit evidence'}),N('cw',470,420,{label:'Review plan'})],edges:[{from:'app',to:'alb'},{from:'alb',to:'rds'},{from:'rds',to:'s3'},{from:'s3',to:'cw'}],panels:[{id:'risk',title:'Declared risk / owner'},{id:'proof',title:'Verified boundary / remaining test'}],steps:[
    {say:'Define checkout and its payment/email dependencies before reviewing the diagram. Marketing availability is not checkout availability.',panels:{risk:['Owner:Neha; accepted-order correctness/SLO required','Review current lens and scope'],proof:['Gather config, runtime and business evidence']}},
    {say:'The ALB name exists, but no correct 5xx alarm is configured. Missing operational detection is a declared course risk.',panels:{risk:['Operational Excellence:missing reviewed detection','Owner:Ravi; exact unit/dimension/period/actions'],proof:['Creating an alarm is configuration','Actual signal/action route needs a runtime test']},ask:Q('A newly created alarm says OK but has no fresh samples. What can the review conclude?', 'Configuration may exist; inspect dimensions, sample freshness and actual notification delivery before claiming health',['OK is enough to close the customer SLO because configuration creation includes a complete live load test','Any alarm name establishes monitoring coverage, so the reviewer can omit the metric and destination details','A manualOK override supplies fresh metric data and therefore replaces the missing production measurements'],0,'A stored alarm is not a measured customer outcome. No-data/initial/manual state can mislead; the name alone omits unit, dimensions, signal and delivery scope.')},
    {say:'Orders is Single-AZ with 0 backup days. Configure the stated HA/history contract, then plan a separate isolated restore with order-ID reconciliation.',panels:{risk:['Reliability:HA/backups config absent','Owner:Ravi; recovery drill still needed'],proof:['Available+MultiAZ+7 days is configuration','No RTO/RPO inferred from retention']},ask:Q('After backup retention becomes 7 days, which evidence is still needed for the recovery promise?', 'Restore and reconcile accepted business IDs in an approved environment, recording actual recovery point and elapsed time',['Treat 7 days retention as a 7 minute RTO because the unit conversion is built into the managed database service','Read Available once because instance availability automatically authenticates every restored application dependency','Add one async reader and call RPOzero because a reader endpoint proves every committed order is already current'],1,'Retention is history length, not measured recovery time/data loss. Available does not test dependencies; async replication does not guarantee zero lag or business reconciliation.')},
    {say:'CloudTrail logging is off. Review destination policy, enabled-Region coverage, management selector and future digest configuration. Preserve original S3 evidence.',panels:{risk:['Security:scoped ongoing audit configuration absent','Owner:security operator; verify destination/runtime'],proof:['No historical backfill from creating a trail','Event history is a separate Region/90 day view']}},
    {say:'The budget board compares declared component quotes and critical On-Demand capacity. A Spot discount may lower cost while resource-hours remain unchanged.',panels:{risk:['Cost + Sustainability:distinct objectives','Keep required resilience and useful work'],proof:['No derived uptime/security/carbon score','Need real representative benchmarks']},ask:Q('Same worker count, vCPU and runtime; only Spot pricing changes. Which conclusion follows?', 'Modeled price can fall while resource-hours stay equal; environmental impact needs evidence beyond a discount',['The discount percentage equals the carbon reduction because billing adjustments directly remove processor cycles','Critical-serving resilience is unchanged automatically because a lower price prevents every Spot interruption','A smaller invoice alone proves more useful work per resource-hour even when completed-order counts are missing'],2,'A rate change need not change resource consumption or useful output. Spot interruptions still need planning; carbon impact and business-unit efficiency cannot be inferred from invoice size.')},
    {say:'Record configuration fixes, actual evidence and remaining runtime actions in the improvement plan. Save a new milestone after meaningful progress; assign owner/expiry/rollback.',panels:{risk:['Three declared configuration items can close','Other review risks remain explicitly scoped'],proof:['A review milestone is point-in-time evidence','No certificate or automatic launch approval']}}
   ]},
   {type:'flowlab',title:'🎛️ Trade-off board — constraints before discounts',goal:'Keep 2000 requests/s critical service after worst-AZ loss without relying on Spot; modeled DB≤800 units/s; Multi-AZ+≥7 backup days; logs≥30 days; gross component quote≤$650/month; app≤3000 vCPU-h/month. Start:HA On, 7 days, cache On, Spot 25%, edge On, logs 30 days, profile M.',scenario:'Fictional course inputs, not AWS price quotes or EC2 benchmarks:12 workers, 3 balanced AZs, 100 active hours/month; profiles S/M/L give 350/500/650 requests/s at 70% allowance, 1/2/4 vCPU and$0.18/$0.25/$0.40 worker-hour. Spot assumed 75% discount, never counted as guaranteed critical capacity. DB quote$120single/$240multi per month; backups$2/day-retained/month; cache$35/month; edge$15/month; logs$0.40/day-retained/month. Pressure=400strong/write units/s+1200eligible reads/s×(cache On?20%:100%)+200without public-asset edge offload. Cost/resource model only; actual uptime, p95, security and carbon are unmeasured.',knobs:[{id:'ha',label:'Database HA configuration',min:0,max:1,step:1,value:0,labels:{0:'Single-AZ',1:'Multi-AZ'}},{id:'backups',label:'Backup retention',min:0,max:2,step:1,value:0,labels:{0:'1 day',1:'7 days',2:'14 days'}},{id:'cache',label:'Eligible read cache',min:0,max:1,step:1,value:0,labels:{0:'Off',1:'On (80% hit assumption)'}},{id:'spot',label:'Interruptible Spot share',min:0,max:2,step:1,value:2,labels:{0:'0%',1:'25%',2:'50%'}},{id:'edge',label:'Public asset edge offload',min:0,max:1,step:1,value:0,labels:{0:'Off',1:'On'}},{id:'logs',label:'Required audit retention scenario',min:0,max:2,step:1,value:0,labels:{0:'7 days',1:'30 days',2:'90 days'}},{id:'size',label:'Fictional worker profile',min:0,max:2,step:1,value:0,labels:{0:'S (1 vCPU)',1:'M (2 vCPU)',2:'L (4 vCPU)'}}],model:k=>{const p=plan(k);return {readouts:[{label:'Critical post-AZ capacity; Spot excluded',value:p.capacity.toFixed(0)+' requests/s'},{label:'Modeled DB pressure /800',value:p.db.toFixed(0)+' units/s'},{label:'Declared constraint failures',value:p.risks+' (not official HRIs)'},{label:'Fictional component gross quote',value:'$'+p.cost.toFixed(2)+'/month'},{label:'App resource use only',value:p.cpu+' vCPU-h/month'},{label:'Runtime/customer evidence',value:'Uptime / p95 / carbon unmeasured'}],verdict:{ok:p.ok,text:p.ok?'Declared budgets fit this fictional scenario. Verify real recovery, performance and business outcomes separately.':'Inspect critical capacity, DB, HA/history, retention, cost and resource-hour constraints before choosing a discount.'}};},check:k=>plan(k).ok,lesson:'Documented choice:M, 25% Spot, HA, 7 day backups, cache+edge, 30 day logs→critical capacity 2100 requests/s;DB 640units/s;gross$559.75/month;app 2400 vCPU-h/month. Spot pricing reduces cost while resource-hours stay 2400. These declared assumptions do not predict a production SLO.'},
   {type:'bins',title:'Six pillars — primary question choose karo',instructions:'Choose the primary focus stated in the item. Other pillars may benefit too; explanations name the overlap.',bins:[{id:'op',label:'Operational Excellence'},{id:'sec',label:'Security'},{id:'rel',label:'Reliability'},{id:'perf',label:'Performance Efficiency'},{id:'cost',label:'Cost Optimization'},{id:'sus',label:'Sustainability'}],items:[{text:'Version a small reversible deployment and rehearse its runbook',bin:'op',explain:'Operating/improving safely is the primary objective; reliability benefits too.'},{text:'Scope decrypt/audit permissions and verify the intended principal path',bin:'sec',explain:'Protecting authorized access/traceability is the stated security concern.'},{text:'Restore an isolated DB and reconcile accepted order IDs within recovery objectives',bin:'rel',explain:'Measured recovery/continued business value is reliability, not backup existence alone.'},{text:'Benchmark instance choices against representative response-time/throughput needs',bin:'perf',explain:'Selecting suitable resources from measurements is Performance Efficiency.'},{text:'Choose an appropriate commitment after measuring stable demand and business cost',bin:'cost',explain:'The stated goal is spend/value, with commitment/coverage risk reviewed.'},{text:'Remove unnecessary computations and track resource use per successful order',bin:'sus',explain:'Reducing wasted resources per useful output is the stated sustainability focus; cost may improve too.'}]},
   {type:'match',title:'Risk → primary pillar → evidence',instructions:'Match each observed gap with the most direct improvement/evidence contract.',pairs:[{left:'Repeated console drift, unclear rollback owner',right:'Operations:version changes, owner/runbook and tested rollback',explain:'Repeatability, learning and safe change ownership address the operating gap.'},{left:'Missing scoped management audit delivery',right:'Security:trail permission/selector/config plus delivered log validation',explain:'Configuration is one stage; real logs/digests and validation need separate proof.'},{left:'Backups exist but restoration was never tested',right:'Reliability:isolated restore and business reconciliation against RTO/RPO',explain:'A backup object does not test keys/network/dependencies or actual recovery.'},{left:'Unbenchmarked instance choice misses tail target',right:'Performance:representative workload experiments and fresh tail metrics',explain:'The issue needs suitable resource/algorithm evidence, not an assumed large-instance fix.'},{left:'Idle environment billed through nights',right:'Cost:review schedule/ownership and verify required service windows',explain:'Removing idle spend can help; preserve required availability and capture real savings.'},{left:'Same work/resource-hours, cheaper rate only',right:'Sustainability:measure actual resource/useful-output change separately',explain:'A discount alone changes price, not necessarily physical/resource impact.'}]},
   {type:'triage',title:'🩺 Four incident reports, one vague score',symptom:'Fictional quarterly notes:one DB availability incident, one failed restore rehearsal, one unreviewed console change andone customer error spike without an alarm. Reviewer wants a defensible plan, not a single pillar score.',goal:'Inspect evidence, identify overlapping risks and assign the first verified improvements.',commands:[{cmd:'aws cloudtrail lookup-events --lookup-attributes AttributeKey=EventName,AttributeValue=ModifyDBInstance',out:'TRAINING management event:course-operator changed orders; no reviewed deployment ticket linked',clue:true,note:'Seeded change evidence suggests an operations/change-control gap. Not live collected history.'},{cmd:'aws rds describe-db-instances --db-instance-identifier orders',out:'MultiAZ:false;BackupRetentionPeriod:0;DBInstanceStatus:available',clue:true,note:'Availability of this instance does not meet the stated HA/history contract or prove recoverability.'},{cmd:'aws cloudwatch describe-alarms',out:'MetricAlarms:[]',clue:true,note:'No configured diagnostic alarm in this fixture. Actual end-to-end monitoring needs broader review too.'},{cmd:'cat review.txt',out:'Restore rehearsal blocked by TEST key permission; no accepted-order reconciliation completed',clue:true,note:'Security dependencies and recovery practice overlap; do not call a stored backup a successful restore.'}],questions:[Q('Which report best follows from these four incidents?', 'Prioritize recovery plus change/detection gaps, with security dependencies and owners; several pillars overlap',['Classify every incident only as Reliability and close the others because one primary label must cover the workload','Classify every incident only as Cost because a larger budget automatically prevents unreviewed console changes','Close the review after Available status because that single resource field certifies all six pillar requirements'],0,'Recovery risk is real, but change control/detection and key dependencies add operations/security concerns. One label, spend increase or Available field cannot close all evidence gaps.'),Q('The scanner reaches 0 of 3declared configuration findings. What should the improvement plan say?', 'Record the corrected config and retain named restore, delivery and customer-SLO verification work with owners',['Replace the whole review with the scanner count because zero selected findings certifies every pillar and runtime','Delete the original evidence objects because retaining failed rehearsal records makes the new score look worse','Mark backup recovery completed without a restore because 7 day retention is equivalent to measured recovery time'],1,'Selected config checks can close their stated contracts. Full review/runtime still need evidence; deletion hides learning and retention does not measure recovery.') ]},
   {type:'terminal',title:'🖥️ Repair three declared configuration risks',instructions:'In-app fixture only; no AWS calls. ls/cat show reviewed policy/alarm/scope. Current metric periods and management events are supplied training data.',goal:'<p><b>1.</b> Preserve original orders resource/data, private wa-audit bucket/original.txt/BPA, ALB/topic and seeded events. Apply trail-policy.json to wa-audit; expected exact shop-review SourceArn/account path.</p><p><b>2.</b> Modify orders to Multi-AZ and backup retention 7 days with --apply-immediately; then wait db-instance-available. Expected original instance available with the new configuration. Real changes can disrupt traffic; this model does not run SQL/failover.</p><p><b>3.</b> PutMetricAlarm from 5xx-alarm.json; full DescribeAlarms review-5xx. Expected ALARM from two supplied Sum counts 8and9&gt;5 per 60s, not a healthy customer SLO. Preserve original topic destination.</p><p><b>4.</b> Create shop-review in us-east-1 using wa-audit with --is-multi-region-trail, --include-global-service-events and --enable-log-file-validation. Default modeled selector records All management events; data events are separate. StartLogging, then full GetTrailStatus. Expected IsLogging:true as configuration only.</p><p>8 actions. Current state and current readback required; deletes, public policy, manual alarmOK, stale status or omitted fixes cannot qualify. Zero of these 3config risks does not prove real restore, S3log/digest delivery/validation, metric-triggered paging or an AWS WA certificate.</p>',account:seed(),files,tasks,solution,hints:['Inspect review.txt, trail-policy.json and 5xx-alarm.json. Preserve originals; separate DB availability, alarm data and trail permission/logging.',solution.slice(0,3).join(' phir '),solution.slice(3,5).join(' phir '),solution.slice(5).join(' phir ')],success:AG.allOf(tasks),successText:'Three declared configuration contracts repaired with original evidence/orders preserved. Correct 5xx alarm detects supplied breaches; current trail logging/management/digest settings read. Actual restore, logs/digests+validation, alarm delivery and customer SLO remain named runtime work.'},
   {type:'docker',title:'🐳 Lab21 — actual selected-risk scanner and gaps',project:'21-wellarch-risk-scan',goal:'Run the owned seed/scan/repair/scan/cleanup sequence and distinguish actual local metadata from unverified runtime.',why:'Moto accepts missing CloudTrail bucket policy, synthesizes delivery status and cannot LookupEvents. A scanner must declare its contracts and limits.',steps:[{text:'From aws-gurukul, read README/lab.py/risk_scan.py, then run the exact launcher.',cmd:'./docker-labs/21-wellarch-risk-scan/seed.sh',expect:'Count 3 before repair, 0 after three declared configuration repairs. 7 behavior checks plus cleanup 8; original TEST evidence retrieved.'},{text:'Read the captured no-policy, selector, initial alarm and event-history gap lines.',expect:'Moto logging accepted without bucket policy; initial alarmOK Unchecked; default selectors[]; LookupEvents HTTP 500. Bucket has only TEST-preserve.txt; no delivered CloudTrail logs/digests or actual ALB.'},{text:'Verify scoped cleanup and the printed owned endpoint closure.',expect:'PASS 8owned fixture resources cleaned; OWNED MOTO STOPPED / LISTENER CLOSED. All clients used the own ephemeral endpoint, even if env.sh banner mentions 4566.'}],observe:Q('Which conclusion is supported by lab21?', 'Three declared configuration contracts and original TEST bytes were checked; full review and production runtime remain unverified',['The 0count proves every AWS WA question passed because the scanner substitutes for all selected lenses and evidence','IsLogging and Moto LatestDeliveryTime prove S3digest files arrived and their signatures were already validated','Initial alarmOK proves representative checkout load passed because a local diagnostic alarm was created successfully'],2,'The scoped scanner/metadata/preservation checks passed. It is not AWS WA Tool; actual delivered objects/digests, validation and representative traffic were absent, so status/initialOK cannot prove them.')},
   {type:'quiz',title:'🎓 Review decisions, not pillar slogans',questions:[
    Q('A team wants a WA review before launch. What should happen first?', 'Define workload/business objectives, dependencies and owners, then gather evidence for the applicable lens',['Start with every available AWS service and add products until the diagram contains one service for each pillar','Answer a fixed 50 questions from memory because selected lenses and workload scope do not change the question set','Choose the cheapest instance first and treat all recovery/security requirements as optional follow-up decorations'],0,'Workload scope/objectives anchor review. Service count, memorized fixed questions and cost before constraints do not establish suitable business architecture.'),
    Q('A reviewer records a new WA milestone after answering questions. What changed directly?', 'The tool captured a point-in-time review state; infrastructure changes and runtime tests still need execution',['Every risky resource was redeployed automatically because milestones apply the improvement plan to the account','All existing high risks were permanently deleted because a new timestamp replaces the need for historical evidence','Database backups were restored automatically because milestone creation is the managed-service recovery test API'],1,'A milestone records review state, notes/risks at a point in time. It does not deploy, delete real risks or run restore tests; improvements/evidence must actually follow.'),
    Q('Critical serving needs 2000 requests/s through interruption and one AZ loss. Spot is cheaper. Decision?', 'Keep an adequate tested non-Spot base and use interruptible capacity where recovery/requirements permit',['Make all serving Spot because a discount percentage is also the guaranteed minimum capacity during interruption','Count desired Spot instances as guaranteed even when defining the interruption failure scenario for critical traffic','Delete the AZ-loss requirement because the lowest hourly invoice is the only criterion in Cost Optimization'],2,'Cost is optimized within constraints. Spot can interrupt, desired is not guaranteed ready capacity and the business failure requirement cannot be silently removed.'),
    Q('Backup retention is 7 days; no restore rehearsal exists. Which claim is defensible?', 'A 7 day recovery-history setting exists; actual recovery time/data point and reconciled application outcomes need tests',['RTO is 7 minutes because the backup-retention number is reused directly as the guaranteed restoration duration','RPO is zero because managed backup configuration means every external dependency commits atomically with the DB','Regional DR is complete because Multi-AZ standby and retained backups are equivalent to tested regional recovery'],3,'Retention is a configuration/history window. It does not measure RTO/RPO, coordinate external atomicity or establish regional recovery; restore/reconciliation evidence is still needed.'),
    Q('Need to investigate a recent management change without a pre-existing trail. First source?', 'CloudTrail Event history in the relevant Region and 90 day window; ongoing trail delivery is a separate setup',['Create a new trail and expect it to backfill every historical data and management event into the destination bucket','Use only CloudWatch target latency because a component percentile identifies the principal of every configuration API','Enable digest creation and assume the feature reconstructs all missing historical management-event log objects'],0,'Event history provides recent Region-scoped management events independently of a new trail. Trails/digests do not backfill missing history; latency does not identify every API principal.'),
    Q('A trail has log-file validation enabled and IsLogging:true. What remains separate?', 'Verify delivered log/digest objects and execute integrity validation; flags alone do not validate historical files',['Treat both flags as evidence that every existing S3 object was automatically signature-validated during UpdateTrail','Remove the bucket permission because enabled validation gives CloudTrail implicit access to every destination path','Call the whole security review complete because a logging flag covers all identity, threat and business controls'],1,'Enabling validation permits digest generation for delivered logs; validation itself is distinct. Destination authorization and broader security review remain necessary; flags do not validate every old object.'),
    Q('A rate discount lowers spend with worker count/vCPU/runtime unchanged. Sustainability conclusion?', 'Resource-hours may be unchanged; measure resource use and environmental impact per useful business output',['Resource consumption falls by the discount percentage because price reductions terminate the equivalent CPU fraction','Completed customer orders necessarily rise because a smaller bill is equivalent to improved useful throughput','Required resilience should be removed next because minimizing resource count takes priority over business constraints'],2,'Price and resource use differ. A discount does not terminate CPU cycles or prove more completed work; sustainability operates within required business/resilience constraints.'),
    Q('Selected scanner reports 0findings; a full review still lacks identity and restore evidence. Report?', 'State exactly which checks passed, retain remaining risks/tests with owners and avoid a full-framework certification claim',['Mark every unanswered lens question as satisfied because zero in any scanner is an official complete WA Tool rating','Delete the initial milestone so that review history contains only the clean result and residual uncertainty disappears','Close all recovery risks because the scanner count measures real failover duration and accepted-order reconciliation'],3,'Scope the evidence honestly. The selected scanner is not a full WA Tool assessment, deletion hides progress/learning and field checks do not measure runtime recovery/business outcomes.')
   ]}
  ],
  interview:{title:'Interview — review evidence and audit repair',instructions:'Four decisions, then repair the original trail without replacing evidence or disabling the other existing safeguards.',questions:[
   Q('An instance benchmark improves p95but increases monthly cost. Which review response is strongest?', 'Compare the measured performance need, budget and alternatives; record the justified trade-off and residual risk',['Reject any faster option because Cost Optimization requires the smallest invoice regardless of stated customer needs','Accept the biggest instance permanently because one good benchmark guarantees all future demand and dependencies','Classify the decision only as Sustainability because more expensive hardware always removes every performance risk'],0,'Trade-offs use requirements and measurements. Cost cannot erase the SLO, one benchmark cannot guarantee future behavior and price alone cannot classify environmental/performance outcomes.'),
   Q('A custom lens marks a team practice satisfied. What should the reviewer remember?', 'Custom lenses are user-defined rather than official AWS content; retain scope, version, notes and evidence',['Every custom answer is an AWS certification because publishing a lens transfers responsibility for runtime proof','A custom lens automatically replaces all Framework questions and removes the need to define a workload boundary','Applying a lens runs all needed recovery drills because questionnaire selection is also the infrastructure test engine'],1,'Custom content is distinct from AWS official Lens Catalog content. Lens application/answers do not certify runtime, remove scoping or execute infrastructure drills.'),
   Q('A security finding has high impact but a full fix takes months. Defensible improvement planning?', 'Prioritize with accountable owners; review interim controls, expiry and residual risk while testing the promised boundary',['Downgrade the recorded impact until the scanner count is zero because a difficult fix should not remain visible','Delete previous milestones because removing old evidence is equivalent to preventing the original failure mode','Mark the risk NotApplicable without changing scope because an expensive remediation should not remain on the backlog'],2,'Prioritization and time-bounded accountable mitigation expose residual risk. Editing the score/deleting evidence hides risk; NotApplicable must reflect the real scope, not the cost or difficulty of a mitigation.'),
   Q('The trail status is old; selectors changed after the last successful read. What supports current readiness?', 'Inspect the current intended selector/permission/logging state and obtain fresh status, retaining separate delivery tests',['Reuse the old status because a previousIsLogging flag proves that every later selector still captures the intended events','Create a second trail name and discard the original evidence because renamed resources inherit all old validation results','Run LookupEvents alone because seeing one prior event guarantees current destination permissions and future digest delivery'],3,'Current config/revision and usable destination matter; a fresh status is still only metadata. Old reads, a replacement name or historical lookup cannot prove future delivery/validation.') ,
   {terminal:{type:'terminal',title:'🖥️ Repair the original paused review trail',instructions:'Original trail exists; keep its identity, evidence and other safeguards.',goal:'<p>shop-review is single-Region/global-off/validation-off and paused; selector excludes management events. Original wa-audit policy is already reviewed. Update the three flags, PutEventSelectors from management.json, StartLogging, then full GetTrailStatus. Preserve original trail identity, bucket/original.txt, DB HA/backups, alarm/topic/ALB and seeded events. 4 actions; expected configuration only, no historical backfill or actual delivered digest validation.</p>',account:seed(true),files,tasks:itasks,solution:isolution,hints:['Inspect original trail/status/selectors. Fix flags and All-management scope; do not replace the trail or evidence.',isolution.slice(0,2).join(' phir '),isolution.slice(2).join(' phir ')],success:AG.allOf(itasks),successText:'Original trail/evidence preserved; reviewed flags, All-management selector, logging and current status restored. Actual delivered files/digests and integrity validation remain separate.'}}
  ]},
  success:['Six pillars ko business risks/evidence aur overlaps se explain kar sakta hoon.','Workload/lens, improvement plan, owner aur milestone ko practical review mein use kar sakta hoon.','Config, runtime/customer outcome aur bounded scanner result distinguish kar sakta hoon.'],
  homework:'<p>Optional approved real-AWS sandbox only; resources/tests can be billable. Define a non-sensitive workload in WA Tool and choose an applicable official/custom lens knowingly. Save a baseline milestone with honest notes and one prioritized improvement/owner/test/rollback. With separate explicit approval, run isolated restore/reconciliation, actual component alert delivery and CloudTrail log/digest validation; preserve production data. Save follow-up evidence/milestone. Cleanup only owned test resources; account for storage, log/data-event, compute and waiting-period charges.</p>',
  cards:[{front:'Six pillars?',back:'Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, Sustainability. Start with the business question; controls can overlap.'},{front:'WA review equals audit certificate?',back:'No; constructive decision/evidence review with improvement plan. A questionnaire or local scanner is not an availability/compliance certificate.'},{front:'Fixed50questions?',back:'No fixed count promise. Selected lens/version and scope determine questions; official Lens Catalog and user-defined custom lenses differ.'},{front:'Milestone runs a deployment?',back:'No. Point-in-time review state. Actual changes and verification must be executed and evidenced separately.'},{front:'Retention versus RTO/RPO?',back:'Retention is stored recovery history. Measure actual recovery time/data point and reconcile business/application outcomes in a proper drill.'},{front:'CloudTrail history/trail/digest?',back:'Recent Region-scoped 90 day management history differs from ongoing selected trail delivery. Enabling future digests does not validate logs.'},{front:'Discount equals sustainability?',back:'Same resource-hours can cost less. Measure resources/environmental impact per useful output, preserving required resilience.'},{front:'Lab21 proves what?',back:'3declared config contracts and TEST preservation, 7 behavior+cleanup 8. Moto permission/delivery/history gaps; no SQL/traffic/log delivery/digest/runtime or full WA assessment.'}]
 }]);
})();
